<script setup>
import AppIcon from './AppIcon.vue'
defineProps({item:Object})
defineEmits(['action','open'])
const typeTone = type => ({competition:'blue',activity:'green',lecture:'violet',employment:'orange',postgraduate:'indigo',academic:'blue',scholarship:'green'}[type] || 'slate')
const dateLabel = item => item.publish_time ? new Date(item.publish_time).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'}) : '校园资讯'
</script>
<template><article class="recommend-card"><div class="card-heading"><span :class="['category-tag',typeTone(item.content_type)]"><span class="category-dot"></span>{{item.content_type_label || '校园信息'}}</span><span v-if="item.score != null" class="match-score" title="综合兴趣、身份、行为和时效的排序分，不代表匹配概率"><AppIcon name="spark" :size="13" /> 推荐分 {{Math.round(item.score*100)}}</span><span v-else class="card-date">{{dateLabel(item)}}</span></div><h3><button class="card-title-button" @click="$emit('open',item);$emit('action',item,'click')">{{item.title}}</button></h3><p class="card-summary">{{item.summary || item.body}}</p><div class="card-meta"><AppIcon name="calendar" :size="14" /><span>{{item.deadline ? '截止 '+new Date(item.deadline).toLocaleDateString('zh-CN') : dateLabel(item)}}</span><span class="meta-dot">·</span><span>{{item.source_department || '校园信息'}}</span></div><div v-if="item.reason" class="card-reason"><AppIcon name="spark" :size="14" /><span>{{item.reason}}</span></div><div class="card-footer"><div class="card-actions"><button class="card-icon-button" title="收藏，优化相关推荐" aria-label="收藏" @click="$emit('action',item,'favorite')"><AppIcon name="heart" :size="17" /></button><button class="card-dismiss" @click="$emit('action',item,'dismiss')">不感兴趣</button></div><button v-if="item.content_type==='activity'" class="card-open" @click="$emit('action',item,'register')">报名活动 <AppIcon name="arrow" :size="16" /></button><button v-else class="card-open" @click="$emit('open',item);$emit('action',item,'click')">阅读全文 <AppIcon name="arrow" :size="16" /></button></div></article></template>
